  $aes.GenerateIV(); # unique IV per file
  $enc = $aes.CreateEncryptor();
  $encData = $enc.TransformFinalBlock($data, 0, $data.Length);
  # RSA encrypt the AES key
  $encKey = $rsa.Encrypt($aes.Key, $true);
